CREATE TABLE IF NOT EXISTS city_history (id INTEGER PRIMARY KEY, city_id INTEGER NOT NULL, snapshot_json TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS city_links (city_id INTEGER NOT NULL, linked_city_id INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(city_id,linked_city_id));
CREATE TABLE IF NOT EXISTS recruiter_cities (recruiter_id INTEGER NOT NULL, city_id INTEGER NOT NULL, is_enabled INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, is_service INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(recruiter_id,city_id,is_service));
CREATE TABLE IF NOT EXISTS service_position_holidays (id INTEGER PRIMARY KEY, position_id INTEGER NOT NULL, holiday_date TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', is_active INTEGER NOT NULL DEFAULT 1, data_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
